WITH flagged AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessions_web_events AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, event_type, CASE WHEN burst_id >= 7 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, ROUND(AVG(burst_id), 2) AS avg_burst_id, COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END) AS add_to_cart_count FROM sessions_web_events GROUP BY is_new_burst_tier, event_type, burst_id_tier
